gt:
بالطبع! إليك كودًا لروبوت Discord باستخدام **Discord.js v14** يُفعّل أمر `/ban` لحظر الأعضاء. يتطلب هذا الكود استخدام أوامر سلاش (Slash Commands)، ويجب أن يكون للروبوت الصلاحيات المناسبة (مثل `Ban Members`) للعمل بشكل صحيح.

> ⚠️ **ملاحظة**: تأكد من تفعيل Gateway Intents المناسبة على لوحة تحكم Discord وتحديث `config.json` أو المتغيرات البيئية ببياناتك.

---

### 📁 1. هيكل المشروع البسيط:
```
bot/
├── index.js
├── commands/
│   └── ban.js
└── package.json
```

---

### 🔧 2. `index.js` – الملف الرئيسي

```javascript
const { Client, Collection, GatewayIntentBits, REST, Routes } = require('discord.js');
const fs = require('fs');
const path = require('path');
require('dotenv').config();

const client = new Client({
    intents: [
        GatewayIntentBits.Guilds,
        GatewayIntentBits.GuildMembers,
        GatewayIntentBits.GuildMessages
    ]
});

client.commands = new Collection();

// قراءة ملفات الأوامر من مجلد commands
const commands = [];
const commandFiles = fs.readdirSync('./commands').filter(file => file.endsWith('.js'));

for (const file of commandFiles) {
    const filePath = path.join('./commands', file);
    const command = require(filePath);
    client.commands.set(command.data.name, command);
    commands.push(command.data.toJSON());
}

// تسجيل الأوامر السلاش (يمكنك تغيير guildId لتسجيل عالميًا)
const rest = new REST({ version: '10' }).setToken(process.env.TOKEN);
const guildId = '123456789012345678'; // غيّرها إلى ID السيرفر الخاص بك

(async () => {
    try {
        console.log('يتم تحديث أوامر السلاش...');
        await rest.put(
            Routes.applicationGuildCommands(process.env.CLIENT_ID, guildId),
            { body: commands }
        );
        console.log('تم تحديث أوامر السلاش بنجاح!');
    } catch (error) {
        console.error('خطأ في تحديث أوامر السلاش:', error);
    }
})();

client.once('ready', () => {
    console.log(`الروبوت جاهز باسم ${client.user.tag}`);
});

client.on('interactionCreate', async interaction => {
    if (!interaction.isCommand()) return;

    const command = client.commands.get(interaction.commandName);

    if (!command) return;

    try {
        await command.execute(interaction);
    } catch (error) {
        console.error(error);
        await interaction.reply({ content: 'حدث خطأ أثناء تنفيذ هذا الأمر!', ephemeral: true });
    }
});

client.login(process.env.TOKEN);
```

