### 🛠️ 3. `commands/ban.js` – أمر الحظر

```javascript
const { SlashCommandBuilder, PermissionsBitField } = require('discord.js');

module.exports = {
    data: new SlashCommandBuilder()
        .setName('ban')
        .setDescription('يحظر عضوًا من السيرفر.')
        .addUserOption(option =>
            option.setName('العضو')
                .setDescription('العضو الذي تريد حظره')
                .setRequired(true))
        .addStringOption(option =>
            option.setName('السبب')
                .setDescription('السبب في الحظر')
                .setRequired(false)),

    async execute(interaction) {
        // تحقق من صلاحيات المستخدم
        if (!interaction.member.permissions.has(PermissionsBitField.Flags.BanMembers)) {
            return await interaction.reply({
                content: '❌ ليس لديك صلاحية حظر الأعضاء.',
                ephemeral: true
            });
        }

        const user = interaction.options.getUser('العضو');
        const reason = interaction.options.getString('السبب') || 'لا يوجد سبب محدد';
        const member = await interaction.guild.members.fetch(user.id).catch(() => null);

        // التحقق من أن العضو موجود في السيرفر
        if (!member) {
            return await interaction.reply({
                content: '❌ هذا العضو ليس في السيرفر.',
                ephemeral: true
            });
        }

        // منع حظر نفسك أو الحارس (الروبوت) أو مالك السيرفر
        if (user.id === interaction.user.id) {
            return await interaction.reply({
                content: '❌ لا يمكنك حظر نفسك!',
                ephemeral: true
            });
        }

        if (user.id === interaction.client.user.id) {
            return await interaction.reply({
                content: '❌ لا يمكنني حظر نفسي!',
                ephemeral: true
            });
        }

        if (member.permissions.has(PermissionsBitField.Flags.Administrator)) {
            return await interaction.reply({
                content: '❌ لا يمكنك حظر مسؤول!',
                ephemeral: true
            });
        }

        try {
            await member.ban({ reason });
            await interaction.reply({
                content: `✅ تم حظر ${user.tag} بنجاح!\nالسبب: ${reason}`
            });
        } catch (error) {
            console.error(error);
            await interaction.reply({
                content: '❌ تعذر حظر هذا العضو (قد تكون صلاحيات الروبوت غير كافية).',
                ephemeral: true
            });
        }
    }
};
```

